=== rateplan/BaseRatePlanStrategy.java
     1	package com.pousada.rateplan;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public abstract class BaseRatePlanStrategy implements RatePlanStrategy {
     9	
    10	    protected BigDecimal round(BigDecimal value) {
    11	        return value.setScale(2, RoundingMode.HALF_EVEN);
    12	    }
    13	
    14	    protected boolean isHighSeason(LocalDate date) {
    15	        Month month = date.getMonth();
    16	        int day = date.getDayOfMonth();
    17	
    18	        if (month == Month.DECEMBER && day >= 15) {
    19	            return true;
    20	        }
    21	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    22	            return true;
    23	        }
    24	        if (month == Month.JULY) {
    25	            return true;
    26	        }
    27	
    28	        return false;
    29	    }
    30	
    31	    protected BigDecimal calculateNightRate(BigDecimal baseRate, LocalDate date) {
    32	        if (isHighSeason(date)) {
    33	            return round(baseRate.multiply(new BigDecimal("1.20")));
    34	        }
    35	        return baseRate;
    36	    }
    37	
    38	    protected BigDecimal calculateNightlySubtotal(PricingContext context) {
    39	        BigDecimal baseRate = context.getRoomType().getNightlyRate();
    40	        BigDecimal total = BigDecimal.ZERO;
    41	
    42	        LocalDate current = context.getCheckIn();
    43	        while (current.isBefore(context.getCheckOut())) {
    44	            total = total.add(calculateNightRate(baseRate, current));
    45	            current = current.plusDays(1);
    46	        }
    47	
    48	        return round(total);
    49	    }
    50	}
