     9	    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
    10	        "TECNOSUL", new BigDecimal("0.12"),
    11	        "AGROVALE", new BigDecimal("0.18"),
    12	        "FARMAVIDA", new BigDecimal("0.25")
    13	    );
    14	
    15	    @Override
    16	    public void validate(PricingContext context) {
    17	        if (context.getCompanyCode() == null || context.getCompanyCode().isEmpty()) {
    18	            throw new BusinessException("INVALID_REQUEST",
    19	                "Company code is required for corporate rate plan", 400);
    20	        }
    21	
    22	        if (!COMPANY_DISCOUNTS.containsKey(context.getCompanyCode())) {
    23	            throw new BusinessException("INVALID_REQUEST",
    24	                "Invalid company code: " + context.getCompanyCode(), 400);
    25	        }
    26	    }
    27	
    28	    @Override
    29	    public PricingResult calculatePrice(PricingContext context) {
    30	        BigDecimal subtotal = calculateNightlySubtotal(context);
    31	        BigDecimal discountRate = COMPANY_DISCOUNTS.get(context.getCompanyCode());
    32	        BigDecimal discount = round(subtotal.multiply(discountRate));
    33	        BigDecimal total = round(subtotal.subtract(discount));
    34	
    35	        return new PricingResult(subtotal, discount, total);
    36	    }
