    17	public class ReservationService {
    18	
    19	    private final List<Reservation> reservations = new ArrayList<>();
    20	    private final AtomicLong nextId = new AtomicLong(1);
    21	    private final RoomService roomService;
    22	    private final MessageService messageService;
    23	
    24	    public ReservationService(RoomService roomService, MessageService messageService) {
    25	        this.roomService = roomService;
    26	        this.messageService = messageService;
    27	    }
    28	
    29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    30	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    31	                                        int guests, RatePlan ratePlan, String companyCode) {
    32	        Room room = roomService.getRoom(roomNumber);
    33	
    34	        if (guests < 1) {
    35	            throw new BusinessException("INVALID_REQUEST", "At least one guest is required", 400);
    36	        }
    37	
    38	        if (guests > room.getCapacity()) {
    39	            throw new BusinessException("CAPACITY_EXCEEDED",
    40	                "Room capacity exceeded. Maximum: " + room.getCapacity(), 422);
    41	        }
    42	
    43	        int nights = (int) checkIn.until(checkOut, java.time.temporal.ChronoUnit.DAYS);
    44	
    45	        PricingContext context = new PricingContext(room.getType(), checkIn, checkOut,
    46	                                                    guests, companyCode);
    47	
    48	        RatePlanStrategy strategy = RatePlanRegistry.getStrategy(ratePlan);
    49	        strategy.validate(context);
    50	
    51	        PricingResult pricing = strategy.calculatePrice(context);
    52	
    53	        checkRoomAvailability(roomNumber, checkIn, checkOut, null);
    54	
    55	        Reservation reservation = new Reservation(
    56	            nextId.getAndIncrement(),
    57	            roomNumber,
    58	            guestName,
    59	            guestEmail,
    60	            guestCpf,
    61	            checkIn,
    62	            checkOut,
    63	            guests,
    64	            ratePlan,
    65	            companyCode,
    66	            nights,
    67	            pricing.getSubtotal(),
    68	            pricing.getDiscount(),
    69	            pricing.getTotal()
    70	        );
    71	
    72	        reservations.add(reservation);
    73	        return reservation;
    74	    }
    75	
    76	    public Reservation getReservation(long id) {
    77	        return reservations.stream()
    78	            .filter(r -> r.getId() == id)
    79	            .findFirst()
    80	            .orElseThrow(() -> new BusinessException("RESERVATION_NOT_FOUND",
    81	                "Reservation not found: " + id, 404));
    82	    }
    83	
    84	    public Reservation confirmReservation(long id) {
    85	        Reservation reservation = getReservation(id);
    86	
    87	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    88	            throw new BusinessException("OPERATION_NOT_ALLOWED",
    89	                "Can only confirm pending reservations", 409);
    90	        }
    91	
    92	        reservation.setStatus(ReservationStatus.CONFIRMED);
    93	        reservation.setAmountPaid(reservation.getTotal());
    94	
    95	        sendConfirmationEmail(reservation);
    96	
    97	        return reservation;
