   101	        Reservation reservation = getReservation(id);
   102	
   103	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   104	            throw new BusinessException("OPERATION_NOT_ALLOWED",
   105	                "Can only check-in confirmed reservations", 409);
   106	        }
   107	
   108	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   109	        return reservation;
   110	    }
   111	
   112	    public Reservation checkOut(long id) {
   113	        Reservation reservation = getReservation(id);
   114	
   115	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   116	            throw new BusinessException("OPERATION_NOT_ALLOWED",
   117	                "Can only check-out checked-in reservations", 409);
   118	        }
   119	
   120	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   121	        return reservation;
   122	    }
   123	
   124	    public Reservation cancelReservation(long id) {
   125	        Reservation reservation = getReservation(id);
   126	
   127	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   128	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   129	            throw new BusinessException("OPERATION_NOT_ALLOWED",
   130	                "Can only cancel pending or confirmed reservations", 409);
   131	        }
   132	
   133	        RatePlanStrategy strategy = RatePlanRegistry.getStrategy(reservation.getRatePlan());
   134	        BigDecimal refund = strategy.calculateRefund(reservation.getAmountPaid());
   135	
   136	        reservation.setStatus(ReservationStatus.CANCELLED);
   137	        reservation.setRefund(refund);
   138	
   139	        return reservation;
