   142	    public String generateDocument(long id) {
   143	        Reservation reservation = getReservation(id);
   144	
   145	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   146	            throw new BusinessException("OPERATION_NOT_ALLOWED",
   147	                "Document only available for paid reservations", 409);
   148	        }
   149	
   150	        return formatDocument(reservation);
