   153	    private void checkRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut,
   154	                                      Long excludeReservationId) {
   155	        boolean hasConflict = reservations.stream()
   156	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   157	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   158	            .filter(r -> excludeReservationId == null || r.getId() != excludeReservationId)
   159	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   160	
