   112	    public Reservation checkOut(long id) {
   113	        Reservation reservation = getReservation(id);
   114	
   115	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   116	            throw new BusinessException("OPERATION_NOT_ALLOWED",
