   143	        Reservation reservation = getReservation(id);
   144	
   145	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   146	            throw new BusinessException("OPERATION_NOT_ALLOWED",
   147	                "Document only available for paid reservations", 409);
   148	        }
   149	
   150	        return formatDocument(reservation);
   151	    }
   152	
   153	    private void checkRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut,
   154	                                      Long excludeReservationId) {
   155	        boolean hasConflict = reservations.stream()
   156	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   157	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   158	            .filter(r -> excludeReservationId == null || r.getId() != excludeReservationId)
   159	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   160	
   161	        if (hasConflict) {
   162	            throw new BusinessException("ROOM_UNAVAILABLE",
   163	                "Room not available for the selected dates", 409);
   164	        }
   165	    }
   166	
   167	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   168	        return start1.isBefore(end2) && start2.isBefore(end1);
   169	    }
   170	
   171	    private void sendConfirmationEmail(Reservation reservation) {
   172	        String subject = "Reserva confirmada - Pousada Maré Alta";
   173	        String body = String.format(
   174	            "Olá, %s!\n\n" +
   175	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   176	            "%s\n\n" +
   177	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   178	            "Até breve!",
   179	            reservation.getGuestName(),
   180	            formatDocument(reservation)
   181	        );
   182	
   183	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
   184	    }
   185	
   186	    private String formatDocument(Reservation reservation) {
   187	        Room room = roomService.getRoom(reservation.getRoomNumber());
   188	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   189	
   190	        StringBuilder doc = new StringBuilder();
   191	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   192	        doc.append("Hóspede: ").append(reservation.getGuestName())
   193	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   194	        doc.append("Quarto: ").append(reservation.getRoomNumber())
   195	           .append(" (").append(room.getType()).append(")\n");
   196	        doc.append("Entrada: ").append(reservation.getCheckIn().format(dateFormatter))
   197	           .append(" | Saída: ").append(reservation.getCheckOut().format(dateFormatter))
   198	           .append(" | ").append(reservation.getNights())
   199	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   200	        doc.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
   201	
   202	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   203	            doc.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
   204	        }
   205	
   206	        doc.append("Total: ").append(formatMoney(reservation.getTotal()));
   207	
   208	        return doc.toString();
   209	    }
   210	
   211	    private String formatCpf(String cpf) {
   212	        if (cpf.length() == 11) {
   213	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
   214	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
   215	        }
   216	        return cpf;
   217	    }
   218	
   219	    private String formatMoney(BigDecimal amount) {
   220	        return String.format("R$ %,.2f", amount).replace(",", "X")
   221	                                                 .replace(".", ",")
   222	                                                 .replace("X", ".");
   223	    }
   224	
   225	    public List<Reservation> getAllReservations() {
   226	        return new ArrayList<>(reservations);
   227	    }
   228	}
