    12	import java.util.List;
    13	import java.util.stream.Collectors;
    14	
    15	public class ReportService {
    16	
    17	    private final ReservationService reservationService;
    18	    private final RoomService roomService;
    19	    private static final DateTimeFormatter CSV_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    20	
    21	    public ReportService(ReservationService reservationService, RoomService roomService) {
    22	        this.reservationService = reservationService;
    23	        this.roomService = roomService;
    24	    }
    25	
    26	    public String generateOccupancyReport(LocalDate date) {
    27	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
    28	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    29	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
    30	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
    31	            .filter(r -> occupiesNight(r, date))
    32	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    33	            .collect(Collectors.toList());
    34	
    35	        StringBuilder csv = new StringBuilder();
    36	        csv.append("room,type,reservation,check_in,check_out\n");
    37	
    38	        for (Reservation r : occupiedReservations) {
    39	            Room room = roomService.getRoom(r.getRoomNumber());
    40	            csv.append(r.getRoomNumber()).append(",")
    41	               .append(room.getType()).append(",")
    42	               .append(r.getId()).append(",")
    43	               .append(r.getCheckIn().format(CSV_DATE_FORMAT)).append(",")
    44	               .append(r.getCheckOut().format(CSV_DATE_FORMAT)).append("\n");
    45	        }
    46	
    47	        int totalRooms = roomService.getAllRooms().size();
    48	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
    49	
    50	        return csv.toString();
    51	    }
    52	
    53	    public String generateRevenueReport(YearMonth month) {
    54	        List<Reservation> relevantReservations = reservationService.getAllReservations().stream()
    55	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    56	            .filter(r -> getRevenue(r).compareTo(BigDecimal.ZERO) > 0)
    57	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    58	                             .thenComparing(Reservation::getId))
    59	            .collect(Collectors.toList());
    60	
    61	        StringBuilder csv = new StringBuilder();
    62	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    63	
    64	        BigDecimal total = BigDecimal.ZERO;
    65	
    66	        for (Reservation r : relevantReservations) {
    67	            BigDecimal revenue = getRevenue(r);
    68	            csv.append(r.getId()).append(",")
    69	               .append(r.getRoomNumber()).append(",")
    70	               .append(r.getCheckIn().format(CSV_DATE_FORMAT)).append(",")
    71	               .append(r.getCheckOut().format(CSV_DATE_FORMAT)).append(",")
    72	               .append(r.getStatus()).append(",")
    73	               .append(formatCsvAmount(revenue)).append("\n");
    74	            total = total.add(revenue);
    75	        }
    76	
    77	        csv.append("total,").append(formatCsvAmount(total));
    78	
    79	        return csv.toString();
    80	    }
    81	
    82	    private boolean occupiesNight(Reservation reservation, LocalDate night) {
    83	        return !reservation.getCheckIn().isAfter(night) &&
    84	               reservation.getCheckOut().isAfter(night);
    85	    }
    86	
    87	    private BigDecimal getRevenue(Reservation reservation) {
    88	        BigDecimal paid = reservation.getAmountPaid();
    89	        BigDecimal refunded = reservation.getRefund() != null ?
    90	                             reservation.getRefund() : BigDecimal.ZERO;
    91	        return paid.subtract(refunded);
    92	    }
    93	
    94	    private String formatCsvAmount(BigDecimal amount) {
    95	        return amount.toString();
    96	    }
    97	}
