    10	public class RoomService {
    11	
    12	    private final Map<String, Room> rooms;
    13	
    14	    public RoomService() {
    15	        this.rooms = Map.of(
    16	            "101", new Room("101", RoomType.STANDARD),
    17	            "102", new Room("102", RoomType.STANDARD),
    18	            "201", new Room("201", RoomType.DELUXE),
    19	            "202", new Room("202", RoomType.DELUXE),
    20	            "301", new Room("301", RoomType.SUITE)
    21	        );
    22	    }
    23	
    24	    public List<Room> getAllRooms() {
    25	        return rooms.values().stream()
    26	            .sorted((r1, r2) -> r1.getNumber().compareTo(r2.getNumber()))
    27	            .collect(Collectors.toList());
    28	    }
    29	
    30	    public Room getRoom(String number) {
    31	        Room room = rooms.get(number);
    32	        if (room == null) {
    33	            throw new BusinessException("ROOM_NOT_FOUND", "Room not found: " + number, 404);
    34	        }
    35	        return room;
    36	    }
    37	}
